from PIL import Image
import numpy as np
im = Image.open('radiograph.jpg').convert('L')
a = np.array(im)
mask = a>225
mask[:400,:]=False; mask[950:,:]=False; mask[:, :200]=False; mask[:,-200:]=False
# label-ish via flood on downsampled
from collections import deque
small = mask[::4,::4]
seen=np.zeros_like(small,bool)
H,W=small.shape
comps=[]
for i in range(H):
  for j in range(W):
    if small[i,j] and not seen[i,j]:
      q=deque([(i,j)]); seen[i,j]=True; pts=[]
      while q:
        y,x=q.popleft(); pts.append((y,x))
        for dy in(-1,0,1):
          for dx in(-1,0,1):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and small[ny,nx] and not seen[ny,nx]:
              seen[ny,nx]=True; q.append((ny,nx))
      if len(pts)>25:
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        comps.append((len(pts), min(xs)*4,min(ys)*4,max(xs)*4,max(ys)*4))
for c in sorted(comps, reverse=True):
    print(c)
"", "description": "Connected-component analysis of bright restorations"}
